// Packs the Hunspell English dictionaries (dictionary-en, dictionary-en-gb) into modules the
// spelling checker loads on first use (src/check/dict/*.gen.ts): each file compressed and
// base64 encoded, so both builds can bundle them without a loader of their own.
// Runs after `npm install`; the generated files are not committed.
import { mkdirSync, readFileSync, writeFileSync } from 'node:fs';
import { deflateSync } from 'node:zlib';

const out = 'src/check/dict';
mkdirSync(out, { recursive: true });
for (const [pkg, file] of [
  ['dictionary-en', 'en-us'],
  ['dictionary-en-gb', 'en-gb'],
]) {
  const pack = (name) => deflateSync(readFileSync(`node_modules/${pkg}/${name}`), { level: 9 }).toString('base64');
  const { version } = JSON.parse(readFileSync(`node_modules/${pkg}/package.json`, 'utf8'));
  writeFileSync(
    `${out}/${file}.gen.ts`,
    `// Generated by scripts/build-dictionaries.mjs from ${pkg} ${version} (MIT AND BSD); do not edit.\n` +
      `export const aff = '${pack('index.aff')}';\nexport const dic = '${pack('index.dic')}';\n`,
  );
}
console.log(`wrote ${out}/en-us.gen.ts and ${out}/en-gb.gen.ts`);
